 1.5 &lt;a href=&#34;#15-%E5%AD%97%E7%AC%A6%E4%B8%B2%E7%9A%84%E6%A0%BC%E5%BC%8F%E5%8C%96&#34;&gt;字符串的格式化&lt;/a&gt;&lt;br /&gt;
 1.6 &lt;a href=&#34;#16-%E5%AD%97%E7%AC%A6%E4%B8%B2%E7%9A%84%E8%BF%9E%E6%8E%A5%E4%B8%8E%E9%87%8D%E5%A4%8D&#34;&gt;字符串的连接与重复&lt;/a&gt;&lt;br /&gt;
