 2.1 &lt;a href=&#34;#21-%E5%9F%BA%E6%9C%AC%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B%E8%BD%AC%E6%8D%A2&#34;&gt;基本数据类型转换&lt;/a&gt;&lt;br /&gt;
