 2.3 &lt;a href=&#34;#23-%E5%B8%B8%E7%94%A8%E6%95%B0%E5%AD%A6%E5%87%BD%E6%95%B0&#34;&gt;常用数学函数&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;#3-%E5%88%97%E8%A1%A8&#34;&gt;列表&lt;/a&gt;&lt;br /&gt;
