 3.7 &lt;a href=&#34;#37-%E5%88%97%E8%A1%A8%E5%85%83%E7%B4%A0%E7%9A%84%E6%8E%92%E5%BA%8F&#34;&gt;列表元素的排序&lt;/a&gt;&lt;br /&gt;
 3.8 &lt;a href=&#34;#38-%E5%88%97%E8%A1%A8%E7%9A%84%E5%85%B6%E4%BB%96%E6%93%8D%E4%BD%9C&#34;&gt;列表的其他操作&lt;/a&gt;&lt;/li&gt;
