 4.2 &lt;a href=&#34;#42-%E5%85%83%E7%BB%84%E7%9A%84%E5%B8%B8%E7%94%A8%E6%93%8D%E4%BD%9C&#34;&gt;元组的常用操作&lt;/a&gt;&lt;br /&gt;
 4.3 &lt;a href=&#34;#43-%E5%BA%8F%E5%88%97%E8%A7%A3%E5%8C%85&#34;&gt;序列解包&lt;/a&gt;&lt;/li&gt;
